(function(E){ const x = E["ai-m2"] = E["ai-m2"] || {units:{}}; x.units["ai-6"] = {"grammar":{"id":"c-ai-6-g","level":"B1","course":"ai-internet","unit":"ai-6","title":"Saying what is wrong: it doesn't say, I would add","titleTr":"Neyin yanlış olduğunu söylemek: it doesn't say, I would add","titleFa":"ایراد را بگو: it doesn't say، I would add","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["It doesn't say + who/what","It doesn't say who it is for."],["I would add + noun","I would add a word limit."],["Keep X, but + verb","Keep the first paragraph, but shorten the rest."]]},"wrong":"It don't say who is it for.","right":"It doesn't say who it is for.","blank":{"sentence":"The prompt ___ say who will read it.","word":"doesn't","distractors":["don't","isn't"]},"wrong2":"I would adding a word limit.","right2":"I would add a word limit.","blank2":{"sentence":"I would ___ the real date.","word":"add","distractors":["adding","to add"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Use it doesn't say for what is missing.","tr":"Eksik olan için it doesn't say kullan.","fa":"برای چیزی که کم است از it doesn't say استفاده کن.","ex":"It doesn't say how long."},{"en":"Use I would add for your fix.","tr":"Düzeltmen için I would add kullan.","fa":"برای اصلاحت از I would add استفاده کن.","ex":"I would add the delivery date."},{"en":"Use keep and but for a follow-up.","tr":"Takip mesajında keep ve but kullan.","fa":"در پیام پیگیری از keep و but استفاده کن.","ex":"Keep the title, but rephrase the rest."}],"test":{"en":"Did you name what is missing, and the fix?","tr":"Eksik olanı ve düzeltmeyi söyledin mi?","fa":"چیزی که کم است و اصلاحش را گفته‌ای؟"}},"errorWatch":[{"find":["it don't say"],"fix":{"en":"Use it doesn't say.","tr":"it doesn't say kullan.","fa":"از it doesn't say استفاده کن."}}]},"b2":{"id":"c-ai-6-b2","level":"B2","course":"ai-internet","unit":"ai-6","track":"B2","title":"Softer feedback: might, it may help to","titleTr":"Daha yumuşak geri bildirim: might, it may help to","titleFa":"بازخورد نرم‌تر: might، it may help to","formsTable":{"headers":{"en":["Direct","Softer"],"tr":["Doğrudan","Daha yumuşak"],"fa":["مستقیم","نرم‌تر"]},"rows":[["Add a limit.","It may help to add a limit."],["This is wrong.","This might not be what you need."]]},"wrong":"It may help adding a limit.","right":"It may help to add a limit.","blank":{"sentence":"It may help ___ the reader.","word":"to name","distractors":["naming","name"]},"wrong2":"This might not to be clear.","right2":"This might not be clear.","blank2":{"sentence":"This might not ___ clear enough.","word":"be","distractors":["to be","being"]},"expParts":{"tryFrom":"blank","rule":[{"en":"It may help to + verb gives advice gently.","tr":"It may help to + fiil nazikçe öneri verir.","fa":"بعد از It may help to فعل می‌آید و پیشنهادت را نرم می‌کند.","ex":"It may help to name the reader."},{"en":"Might not softens a problem.","tr":"might not bir sorunu yumuşatır.","fa":"might not مشکل را نرم‌تر می‌گوید.","ex":"This might not be clear enough."}],"test":{"en":"Are you speaking to a colleague? Soften it.","tr":"Bir meslektaşınla mı konuşuyorsun? Yumuşat.","fa":"با همکارت حرف می‌زنی؟ نرم‌ترش کن."}},"errorWatch":[{"find":["might not to"],"fix":{"en":"After might not, use the base verb.","tr":"might not'tan sonra yalın fiil gelir.","fa":"بعد از might not شکل ساده‌ی فعل می‌آید."}}],"useIn":{"en":"B2: give your feedback on a colleague's prompt with might or it may help to.","tr":"B2: Bir meslektaşının prompt'una geri bildirimini might ya da it may help to ile ver.","fa":"B2: بازخوردت درباره‌ی پرامپت همکارت را با might یا it may help to بده."},"exitItem":{"from":"ai-6","kind":"blank","prompt":"It may help ___ a word limit.","options":["to add","adding","add"],"correct":0}},"vocab":{"id":"c-ai-6-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-6","goals":["career"],"title":{"en":"Fixing prompts","tr":"Prompt düzeltmek","fa":"درست کردن پرامپت"},"cards":[{"word":"follow-up","sentence":"Write a follow-up in the same chat.","meaning":{"en":"Your next message in the same chat.","tr":"Aynı sohbetteki bir sonraki mesajın.","fa":"پیام بعدی تو در همان گفت‌وگو."}},{"word":"shorten","sentence":"Shorten this to 60 words.","meaning":{"en":"To make shorter.","tr":"Kısaltmak.","fa":"کوتاه کردن."}},{"word":"rephrase","sentence":"Rephrase the second sentence.","meaning":{"en":"To say in other words.","tr":"Başka kelimelerle söylemek.","fa":"با کلمه‌های دیگر گفتن."}},{"word":"format","sentence":"Choose a format: email, list or table.","meaning":{"en":"The layout of an answer.","tr":"Yanıtın düzeni.","fa":"قالب و چیدمان جواب."}}]},"judge":{"id":"c-ai-6-j","course":"ai-internet","unit":"ai-6","type":"judge","mode":"single","title":{"en":"What was missing?","tr":"Ne eksikti?","fa":"چه چیزی کم بود؟"},"prompt":"What was missing in each prompt?","parts":["Reader","Facts","Limits","Format"],"instruction":{"en":"Read the prompt and the example answer. Choose what was missing.","tr":"Prompt'u ve örnek yanıtı oku. Neyin eksik olduğunu seç.","fa":"پرامپت و جواب نمونه را بخوان. انتخاب کن چه چیزی کم بود."},"items":[{"by":"Example AI answer","prompt":"Summarise this report. [report attached]","answer":"A clear summary, but 900 words long.","present":["Limits"],"fix":{"en":"The content is fine, but nobody set a length. Add: \"in 5 bullet points\".","tr":"İçerik iyi ama kimse uzunluk belirtmemiş. Ekle: \"in 5 bullet points\".","fa":"محتوا خوب است، ولی کسی طول را مشخص نکرده. اضافه کن: «in 5 bullet points»."}},{"by":"Example AI answer","prompt":"Explain our new return policy. [policy attached]","answer":"A correct answer, full of legal words our customers do not know.","present":["Reader"],"fix":{"en":"It is correct but written for the wrong person. Add: \"for customers with no legal knowledge\".","tr":"Doğru ama yanlış kişi için yazılmış. Ekle: \"for customers with no legal knowledge\".","fa":"درست است، ولی برای آدم اشتباهی نوشته شده. اضافه کن: «for customers with no legal knowledge»."}},{"by":"Example AI answer","prompt":"Write a reply to this customer about her refund.","answer":"\"Your refund of 120 euros will arrive in 3 days.\" You never gave these numbers.","present":["Facts"],"fix":{"en":"It invented the amount and the time. Give the real facts, and add: \"Use only these facts\".","tr":"Tutarı ve süreyi uydurdu. Gerçek bilgileri ver ve ekle: \"Use only these facts\".","fa":"مبلغ و زمان را از خودش ساخت. اطلاعات واقعی را بده و اضافه کن: «Use only these facts»."}},{"by":"Example AI answer","prompt":"Compare these three suppliers on price, delivery and warranty. [data attached]","answer":"Three long paragraphs. You cannot compare them quickly.","present":["Format"],"fix":{"en":"The facts are there, but the layout is hard to use. Add: \"as a table with one row per supplier\".","tr":"Bilgiler var ama düzen kullanışsız. Ekle: \"as a table with one row per supplier\".","fa":"اطلاعات هست، ولی قالبش کار را سخت می‌کند. اضافه کن: «as a table with one row per supplier»."}}]},"speaking":{"id":"ai-6","course":"ai-internet","unit":"ai-6","topic":{"en":"Say what went wrong","tr":"Neyin yanlış gittiğini söyle","fa":"بگو چه چیزی اشتباه شد"},"warmup":{"en":"What was the last bad AI answer you saw?","tr":"En son gördüğün kötü yapay zekâ yanıtı neydi?","fa":"آخرین جواب بد هوش مصنوعی که دیدی چه بود؟"},"questions":[{"en":"A colleague's prompt was \"Summarise this report.\" The answer was long and general. Say out loud what was missing and what you would add.","tr":"Bir meslektaşının prompt'u: \"Summarise this report.\" Yanıt uzun ve genel. Neyin eksik olduğunu ve ne ekleyeceğini yüksek sesle söyle.","fa":"پرامپت یک همکار این بود: «Summarise this report.» جواب طولانی و کلی بود. بلند بگو چه چیزی کم بود و چه چیزی اضافه می‌کنی."},{"en":"A colleague's answer has a delivery date nobody gave. Say what was missing and what you would add.","tr":"Bir meslektaşının yanıtında kimsenin vermediği bir teslimat tarihi var. Neyin eksik olduğunu ve ne ekleyeceğini söyle.","fa":"در جواب یکی از همکارانت تاریخ تحویلی هست که کسی نداده. بگو چه چیزی کم بوده و چه اضافه می‌کنی."},{"en":"The answer is good, but too formal. Say your follow-up aloud.","tr":"Yanıt iyi ama fazla resmî. Takip mesajını yüksek sesle söyle.","fa":"جواب خوب است، ولی زیادی رسمی است. پیام پیگیری‌ات را بلند بگو."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"This prompt doesn't say who it's for.","meaning":{"en":"Names what is missing.","tr":"Eksik olanı söyler.","fa":"چیزی را که کم است می‌گوید."}},{"phrase":"It needs the real facts.","meaning":{"en":"Names the fix.","tr":"Düzeltmeyi söyler.","fa":"اصلاح را می‌گوید."}},{"phrase":"I would add a word limit.","meaning":{"en":"Offers a change.","tr":"Bir değişiklik önerir.","fa":"یک تغییر پیشنهاد می‌دهد."}}],"model":"The answer is too long and too general, so the prompt has two problems. It doesn't say who the report is for, and it has no length. I would add \"for our sales team\" and \"in five bullet points\". Then I would try again.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I named what was missing, and what I would add.","tr":"Eksik olanı ve ne ekleyeceğimi söyledim.","fa":"گفتم چه چیزی کم بود و چه اضافه می‌کنم."}]},"writing":{"id":"c-ai-6-w","title":{"en":"Fix this prompt","tr":"Bu prompt'u düzelt","fa":"این پرامپت را درست کن"},"course":"ai-internet","unit":"ai-6","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"ai-final-1","prompt":{"en":"Weak prompt: \"Write something about the meeting change.\" Rewrite it. Use the facts below.","tr":"Zayıf prompt: \"Write something about the meeting change.\" Yeniden yaz. Aşağıdaki bilgileri kullan.","fa":"پرامپت ضعیف: «Write something about the meeting change.» بازنویسی‌اش کن. از اطلاعات زیر استفاده کن."},"model":"Write a short message to my team about a meeting change. Use these facts: Monday's meeting moves from 10:00 to 14:00, the room is still Room 3, and everyone must bring the budget file. Keep it under 40 words, friendly and clear. Format it as a chat message. Use only these facts.","frame":"Write a short message to ___\nUse these facts: ___\nKeep it under ___ words, ...\nUse only these facts.","words":[{"word":"Use only these facts"},{"word":"Write"}],"minWords":25,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"own":{"en":"Now fix a weak prompt of your own. Use made-up names and numbers. Never paste real customer data into any tool.","tr":"Şimdi kendi zayıf bir prompt'unu düzelt. Uydurma ad ve sayılar kullan. Gerçek müşteri bilgilerini hiçbir araca yapıştırma.","fa":"حالا یکی از پرامپت‌های ضعیف خودت را درست کن. از نام‌ها و عددهای ساختگی استفاده کن و اطلاعات واقعی مشتری را هرگز در هیچ ابزاری وارد نکن."},"facts":["Monday's team meeting moves from 10:00 to 14:00.","The room stays the same: Room 3.","Everyone must bring the budget file."],"b2Task":{"en":"B2 track: no starters. Then write one follow-up that makes the answer more formal but keeps the times.","tr":"B2 yolu: hazır başlangıç yok. Sonra yanıtı daha resmî yapan ama saatleri koruyan bir takip mesajı yaz.","fa":"مسیر B2: جمله‌ی آماده نداری. بعد یک پیام پیگیری بنویس که جواب را رسمی‌تر کند، ولی ساعت‌ها را نگه دارد."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Find a recent prompt that gave a bad answer. Fix it and try it again.","tr":"Kötü yanıt almış yakın tarihli bir prompt'unu bul. Düzelt ve yeniden dene.","fa":"پرامپتی را که اخیراً جواب بد گرفته پیدا کن. درستش کن و دوباره امتحان کن."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Write a prompt for a real job you do this week. Check it with the five questions. You won't see an AI answer, but the checking still works.","tr":"Bu hafta yaptığın gerçek bir iş için prompt yaz. Beş soruyla kontrol et. Yapay zekâ yanıtı görmezsin ama kontrol yine işe yarar.","fa":"برای یک کار واقعی این هفته‌ات پرامپت بنویس. با پنج سؤال بررسی‌اش کن. جواب هوش مصنوعی را نمی‌بینی، ولی بررسی همچنان فایده دارد."},"noTool":true}]},"exit":{"id":"c-ai-6-x","course":"ai-internet","unit":"ai-6","type":"exit","items":[{"from":"ai-6","kind":"mcq","prompt":"The answer gives a delivery date you never mentioned. What was missing?","options":["Reader","Facts","Limits"],"correct":1,"why":{"en":"It guessed because it did not have the facts.","tr":"Bilgiler olmadığı için tahmin etti.","fa":"چون اطلاعات را نداشت، حدس زد."},"point":1},{"from":"ai-6","kind":"mcq","prompt":"The answer is correct, but your customer cannot understand the technical words. What was missing?","options":["Reader","Facts","Limits"],"correct":0,"why":{"en":"The prompt did not say who will read it.","tr":"Prompt kimin okuyacağını söylemedi.","fa":"پرامپت نگفته بود چه کسی آن را می‌خواند."},"point":1},{"from":"ai-6","kind":"mcq","prompt":"Which prompt could a new colleague do without asking a question?","options":["Write a thank-you email to a supplier for delivering 200 boxes two days early. Under 50 words, warm and professional.","Write a really good thank-you email to our supplier, please, and make it warm and professional in every line.","Thank the supplier for what happened with the boxes. Keep it short and warm, and make sure it sounds professional."],"correct":0,"why":{"en":"It gives the task, the reader, the facts, the length and the tone.","tr":"Görevi, okuyucuyu, bilgileri, uzunluğu ve üslubu veriyor.","fa":"کار، خواننده، اطلاعات، طول و لحن را می‌گوید."},"point":2},{"from":"ai-6","kind":"mcq","prompt":"The answer is nearly right but too long. What is the best next message?","options":["Keep the first paragraph, but cut the rest to two sentences.","Do it again, but make the whole answer a lot better.","Please try harder and give me a better answer now."],"correct":0,"why":{"en":"It says what to keep and what to change. The others leave the AI guessing.","tr":"Neyin kalacağını ve neyin değişeceğini söylüyor. Diğerleri yapay zekâyı tahmine bırakıyor.","fa":"می‌گوید چه چیزی بماند و چه چیزی تغییر کند. بقیه هوش مصنوعی را به حدس زدن وامی‌دارند."},"point":3},{"from":"ai-6","kind":"mcq","prompt":"You asked about delivery prices, and the whole answer is about payment terms. What do you do?","options":["Fix the prompt and start a new chat.","Ask it to make the answer shorter.","Send the answer anyway."],"correct":0,"why":{"en":"The answer is about the wrong thing, so a follow-up will not help much.","tr":"Yanıt başka bir konuda, bu yüzden takip mesajı pek işe yaramaz.","fa":"جواب درباره‌ی چیز دیگری است، پس پیام پیگیری کمک زیادی نمی‌کند."},"point":3},{"from":"ai-3","kind":"mcq","prompt":"Which text is safe to paste into an AI tool?","options":["[Customer] ordered [Product] on [Date] and wants a refund.","Ayşe Kaya, phone 0532 000 00 00, wants a refund.","Here is our full customer list with email addresses."],"correct":0,"why":{"en":"Placeholders keep names and contact details out of the tool.","tr":"Yer tutucular, ad ve iletişim bilgilerini aracın dışında tutar.","fa":"جای‌نگهدارها نام و اطلاعات تماس را از ابزار دور نگه می‌دارند."}},{"from":"ai-5","kind":"mcq","prompt":"Which prompt keeps the tool inside your text?","options":["Tell me everything you know about our refund rules.","Based only on the policy below, list the refund rules.","Please be careful and list the refund rules correctly."],"correct":1,"why":{"en":"Based only on names the text it must use.","tr":"Based only on, kullanılacak metni belirtir.","fa":"Based only on مشخص می‌کند از کدام متن استفاده شود."}},{"from":"ai-2","kind":"mcq","prompt":"The screen says \"Too many requests\". What does it mean?","options":["You used too much for now.","Your file is wrong.","The tool is not offered there."],"correct":0,"why":{"en":"Wait and try later.","tr":"Bekle, sonra dene.","fa":"صبر کن و بعداً امتحان کن."}}]},"explain":{"id":"c-ai-6-e","course":"ai-internet","unit":"ai-6","type":"explain","level":"B1","title":{"en":"Why did this prompt fail?","tr":"Bu prompt neden işe yaramadı?","fa":"چرا این پرامپت جواب نداد؟"},"objective":{"en":"In this lesson you will learn to find what is missing in a prompt and fix it, in any AI tool.","tr":"Bu derste bir prompt'ta neyin eksik olduğunu bulmayı ve düzeltmeyi öğreneceksin. Hangi aracı kullandığın fark etmez.","fa":"در این درس یاد می‌گیری بفهمی در پرامپت چه چیزی کم است و درستش کنی، در هر ابزار هوش مصنوعی."},"hook":{"en":"A bad answer does not always mean a bad tool. Often the prompt left something out. If you can find the gap, you can usually get a better answer in one or two more messages. A prompt is the message you write to an AI tool.","tr":"Kötü yanıt her zaman kötü araç demek değildir. Çoğu zaman prompt'ta bir şey eksiktir. Eksiği bulursan genellikle bir iki mesajda daha iyi bir yanıt alırsın. Prompt (istem), bir yapay zekâ aracına yazdığın mesajdır.","fa":"جواب بد همیشه به معنای ابزار بد نیست. خیلی وقت‌ها چیزی در پرامپت جا افتاده. اگر آن را پیدا کنی، معمولاً با یکی دو پیام جواب بهتری می‌گیری. پرامپت (⁨prompt)⁩ پیامی است که به ابزار هوش مصنوعی می‌نویسی."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"20"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"5"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Start with the answer","tr":"Yanıttan başla","fa":"از جواب شروع کن"},"body":{"en":"Before you change the prompt, name the problem in the answer. The problem shows you what the prompt was missing.","tr":"Prompt'u değiştirmeden önce yanıttaki sorunun adını koy. Sorun, prompt'ta neyin eksik olduğunu gösterir.","fa":"پیش از تغییر دادن پرامپت، مشکل جواب را مشخص کن. همین مشکل نشان می‌دهد در پرامپت چه چیزی کم بوده."},"steps":[{"en":"You gave no facts, so it used general words.","tr":"Bilgi vermedin, o da genel konuştu.","fa":"اطلاعاتی ندادی، پس کلی‌گویی کرد.","ex":"Too general: add Facts"},{"en":"It filled the gap with a guess.","tr":"Boşluğu tahminle doldurdu.","fa":"جای خالی را با حدس پر کرد.","ex":"Invented details: add Facts"},{"en":"It did not know who will read it.","tr":"Kimin okuyacağını bilmiyordu.","fa":"نمی‌دانست چه کسی آن را می‌خواند.","ex":"Wrong tone or too hard: add Reader"},{"en":"You set no length.","tr":"Uzunluk belirtmedin.","fa":"طولش را مشخص نکردی.","ex":"Too long: add Limits"},{"en":"You did not say email, list or table.","tr":"E-posta, liste ya da tablo demedin.","fa":"نگفتی ایمیل، فهرست یا جدول.","ex":"Hard to use: add Format"}],"tip":{"en":"Limit: a better prompt helps, but it does not make the answer true. You still check the facts.","tr":"Sınır: İyi prompt yardımcı olur ama yanıtı doğru yapmaz. Bilgileri yine kontrol edersin.","fa":"محدودیت: پرامپت بهتر کمک می‌کند، ولی جواب را درست نمی‌کند. اطلاعات را باز هم باید بررسی کنی."}},{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Check the prompt with five questions","tr":"Prompt'u beş soruyla kontrol et","fa":"پرامپت را با پنج سؤال بررسی کن"},"body":{"en":"Use these before you send, or after a bad answer.","tr":"Bunları göndermeden önce ya da kötü bir yanıttan sonra kullan.","fa":"این‌ها را پیش از فرستادن یا بعد از یک جواب بد به کار ببر."},"steps":[{"en":"What should it do?","tr":"Ne yapmalı?","fa":"چه کاری بکند؟","ex":"Task. Write a reply..."},{"en":"Who will read it?","tr":"Kim okuyacak?","fa":"چه کسی می‌خواند؟","ex":"Reader. ...to a customer who is not technical."},{"en":"What must it know? Nothing private.","tr":"Neyi bilmeli? Özel bilgi olmasın.","fa":"چه چیزی باید بداند؟ بدون اطلاعات خصوصی.","ex":"Facts. Order 4471 arrives on 14 May, not 7 May."},{"en":"How long, and in what tone?","tr":"Ne kadar uzun, hangi üslupla?","fa":"چقدر بلند و با چه لحنی؟","ex":"Limits. Under 80 words. Friendly but professional."},{"en":"Email, list or table?","tr":"E-posta, liste ya da tablo?","fa":"ایمیل، فهرست یا جدول؟","ex":"Format. As an email with a subject line."}],"tip":{"en":"Could a new colleague do this job without asking you a question? If not, something is missing.","tr":"Yeni bir meslektaş bu işi sana soru sormadan yapabilir mi? Yapamıyorsa bir şey eksiktir.","fa":"یک همکار جدید می‌تواند بدون هیچ سؤالی این کار را انجام بدهد؟ اگر نه، چیزی کم است."}},{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Weak prompt, strong prompt","tr":"Zayıf prompt, güçlü prompt","fa":"پرامپت ضعیف، پرامپت قوی"},"steps":[{"en":"Reader: now it knows who reads it.","tr":"Okuyucu: artık kimin okuyacağını biliyor.","fa":"خواننده: حالا می‌داند چه کسی می‌خواند.","ex":"to a customer in Germany"},{"en":"Facts: it does not need to guess.","tr":"Bilgiler: tahmin etmesi gerekmiyor.","fa":"اطلاعات: دیگر لازم نیست حدس بزند.","ex":"order 4471 ... 14 May, not 7 May"},{"en":"Limits: AI often adds friendly offers. Stop that here.","tr":"Sınırlar: Yapay zekâ sık sık nazik teklifler ekler. Bunu burada durdur.","fa":"محدودیت‌ها: هوش مصنوعی خیلی وقت‌ها پیشنهادهای مهربانانه اضافه می‌کند. همین‌جا جلویش را بگیر.","ex":"Do not offer a discount"},{"en":"Limits: a number works better than \"short\".","tr":"Sınırlar: Sayı, \"short\" demekten daha nettir.","fa":"محدودیت‌ها: عدد از «⁨short⁩» روشن‌تر است.","ex":"Under 80 words"},{"en":"This makes guessing less likely. It does not stop it, so check.","tr":"Bu, tahmini azaltır ama tamamen önlemez, o yüzden kontrol et.","fa":"این کار احتمال حدس زدن را کم می‌کند، ولی جلویش را کامل نمی‌گیرد؛ پس بررسی کن.","ex":"Use only these facts"}],"phrases":[{"phrase":"Write [what] for [who].\nUse these facts: [facts].\nKeep it [length], [tone].\nFormat: [email / list / table].\nUse only these facts. If something is missing, ask me.","meaning":{"en":"Copy this and fill the brackets","tr":"Bunu kopyala, köşeli parantezleri doldur","fa":"این را کپی کن و داخل کروشه‌ها را پر کن"},"copy":true}],"tip":{"en":"You do not need perfect grammar. Clear facts and the right words usually matter more than small mistakes.","tr":"Kusursuz dil bilgisi gerekmez. Net bilgiler ve doğru kelimeler genellikle küçük hatalardan daha önemlidir.","fa":"به گرامر بی‌نقص نیاز نداری. اطلاعات روشن و کلمه‌های درست معمولاً از اشتباه‌های کوچک مهم‌ترند."}},{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Follow up, or start again?","tr":"Devam mı, baştan mı?","fa":"ادامه بدهی یا از نو شروع کنی؟"},"body":{"en":"The answer is close: write a follow-up. A follow-up is your next message in the same chat. The tool can usually see what came before. The answer is about the wrong thing: fix the prompt and start a new chat.","tr":"Yanıt yakınsa takip mesajı yaz. Takip mesajı (follow-up), aynı sohbetteki bir sonraki mesajındır. Araç genellikle öncekileri görebilir. Yanıt başka bir konudaysa prompt'u düzelt ve yeni bir sohbet başlat.","fa":"اگر جواب نزدیک است، پیام پیگیری بنویس. پیام پیگیری (⁨follow-up)⁩ پیام بعدی تو در همان گفت‌وگوست. ابزار معمولاً پیام‌های قبلی را می‌بیند. اگر جواب درباره‌ی چیز دیگری است، پرامپت را درست کن و گفت‌وگوی جدیدی شروع کن."},"phrases":[{"phrase":"Shorten this to 60 words.","meaning":{"en":"Too long","tr":"Çok uzun","fa":"خیلی طولانی"},"copy":true},{"phrase":"Keep the first paragraph, but make the rest more formal.","meaning":{"en":"Part is good","tr":"Bir kısmı iyi","fa":"بخشی از آن خوب است"},"copy":true},{"phrase":"Rewrite this for a reader with no technical knowledge.","meaning":{"en":"Too hard","tr":"Çok zor","fa":"خیلی سخت"},"copy":true},{"phrase":"Use only the facts above. Remove everything else.","meaning":{"en":"Invented details","tr":"Uydurma ayrıntılar","fa":"جزئیات ساختگی"},"copy":true},{"phrase":"Ask me up to three questions before you answer.","meaning":{"en":"You are not sure what it needs","tr":"Neye ihtiyacı olduğundan emin değilsin","fa":"مطمئن نیستی چه چیزی لازم دارد"},"copy":true}],"tip":{"en":"These work in ChatGPT, Claude, Gemini and Copilot, but answers differ by tool and even by try. Menus and features change.","tr":"Bunlar ChatGPT, Claude, Gemini ve Copilot'ta işe yarar, ama yanıtlar araca ve denemeye göre değişir. Menüler ve özellikler de değişebilir.","fa":"این‌ها در ⁨ChatGPT⁩، ⁨Claude⁩، ⁨Gemini⁩ و ⁨Copilot⁩ کار می‌کنند، ولی جواب‌ها از ابزاری به ابزار دیگر و حتی از باری به بار دیگر فرق دارند. منوها و امکانات هم تغییر می‌کنند."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Saying what is wrong: it doesn't say, I would add","tr":"Neyin yanlış olduğunu söylemek: it doesn't say, I would add","fa":"ایراد را بگو: ⁨it doesn't say⁩، ⁨I would add⁩"},"steps":[{"en":"Use it doesn't say for what is missing.","tr":"Eksik olan için it doesn't say kullan.","fa":"برای چیزی که کم است از ⁨it doesn't say⁩ استفاده کن.","ex":"It doesn't say how long."},{"en":"Use I would add for your fix.","tr":"Düzeltmen için I would add kullan.","fa":"برای اصلاحت از ⁨I would add⁩ استفاده کن.","ex":"I would add the delivery date."},{"en":"Use keep and but for a follow-up.","tr":"Takip mesajında keep ve but kullan.","fa":"در پیام پیگیری از ⁨keep⁩ و ⁨but⁩ استفاده کن.","ex":"Keep the title, but rephrase the rest."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["It doesn't say + who/what","It doesn't say who it is for."],["I would add + noun","I would add a word limit."],["Keep X, but + verb","Keep the first paragraph, but shorten the rest."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Weak prompt, strong prompt","tr":"Zayıf prompt, güçlü prompt","fa":"پرامپت ضعیف، پرامپت قوی"},"item":"Write an email about the late order.\nFacts: a customer in Germany; order 4471 arrives on 14 May, not 7 May; a problem at the factory; no discount.","answer":"Write an email to a customer in Germany. Tell her that order 4471 will arrive on 14 May, not 7 May, because of a problem at the factory. Say sorry once. Do not offer a discount. Under 80 words. Friendly but professional. Use only these facts.","walk":[{"en":"Add the reader and the facts.","tr":"Okuyucuyu ve bilgileri ekle.","fa":"خواننده و اطلاعات را اضافه کن."},{"en":"Add limits: what to leave out, and how long.","tr":"Sınırları ekle: ne çıkarılacak, ne kadar uzun olacak.","fa":"محدودیت‌ها را اضافه کن: چه چیزی حذف شود و چقدر بلند باشد."},{"en":"End with \"Use only these facts\", and still check.","tr":"\"Use only these facts\" ile bitir ve yine de kontrol et.","fa":"با «⁨Use only these facts⁩» تمام کن و باز هم بررسی کن."}],"why":{"en":"The first version leaves the reader, the facts and the limits to the tool. The second gives them, so it has less to guess and the customer gets the true date.","tr":"İlk sürüm okuyucuyu, bilgileri ve sınırları araca bırakır. İkincisi bunları verir; araç daha az tahmin eder ve müşteri doğru tarihi öğrenir.","fa":"نسخه‌ی اول خواننده، اطلاعات و محدودیت‌ها را به ابزار می‌سپارد. نسخه‌ی دوم این‌ها را می‌دهد، پس ابزار کمتر حدس می‌زند و مشتری تاریخ درست را می‌فهمد."}},"quick":{"prompt":"Your prompt: \"Write an email about the late order.\" The answer says \"Dear Customer, we apologise for any inconvenience.\" What should you add?","options":["Reader","Facts","Limits","Format"],"correct":1,"why":{"en":"The answer is too general because it has no facts: no order number, no new date, no reason.","tr":"Yanıt çok genel, çünkü bilgi yok: sipariş numarası, yeni tarih, neden yok.","fa":"جواب خیلی کلی است، چون اطلاعاتی ندارد: نه شماره‌ی سفارش، نه تاریخ جدید، نه دلیل."}},"remember":{"en":"Name the problem first, because it shows what to add. A better prompt helps, but it doesn't make the answer true. You can now find what a prompt left out and fix it by rewriting or following up.","tr":"Önce sorunun adını koy, çünkü ne ekleyeceğini o gösterir. İyi prompt yardımcı olur ama yanıtı doğru yapmaz. Artık bir prompt'ta neyin eksik olduğunu bulup yeniden yazarak ya da takip mesajıyla düzeltebilirsin.","fa":"اول مشکل را مشخص کن، چون نشان می‌دهد چه چیزی اضافه کنی. پرامپت بهتر کمک می‌کند، ولی جواب را درست نمی‌کند. حالا می‌توانی بفهمی پرامپت چه چیزی کم دارد و با بازنویسی یا پیام پیگیری درستش کنی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Softer feedback: might, it may help to","tr":"Daha yumuşak geri bildirim: might, it may help to","fa":"بازخورد نرم‌تر: ⁨might⁩، ⁨it may help to⁩"},"steps":[{"en":"It may help to + verb gives advice gently.","tr":"It may help to + fiil nazikçe öneri verir.","fa":"بعد از ⁨It may help to⁩ فعل می‌آید و پیشنهادت را نرم می‌کند.","ex":"It may help to name the reader."},{"en":"Might not softens a problem.","tr":"might not bir sorunu yumuşatır.","fa":"⁨might not⁩ مشکل را نرم‌تر می‌گوید.","ex":"This might not be clear enough."}],"table":{"headers":{"en":["Direct","Softer"],"tr":["Doğrudan","Daha yumuşak"],"fa":["مستقیم","نرم‌تر"]},"rows":[["Add a limit.","It may help to add a limit."],["This is wrong.","This might not be what you need."]]},"body":{"en":"B2: give your feedback on a colleague's prompt with might or it may help to.","tr":"B2: Bir meslektaşının prompt'una geri bildirimini might ya da it may help to ile ver.","fa":"⁨B2⁩: بازخوردت درباره‌ی پرامپت همکارت را با ⁨might⁩ یا ⁨it may help to⁩ بده."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
